Translate("deDE", "humans", {
	title = "Menschen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Menschen sind das zahlreichste der jüngeren Völker der {link:eastern-kingdoms}Östlichen Königreiche{/link}. Neben Elfen und Zwergen sind sie kurzlebig, doch rastlos, beharrlich und schnell im Lernen. Aus ihren Blutlinien erwuchsen die großen Königreiche des Nordens und des Südens, und aus ihren Reihen kamen die Paladine des {link:holy-light}Heiligen Lichts{/link} und die Magier von {link:dalaran}Dalaran{/link}. Sie haben in den Kriegen gegen die {link:orcs}Orcs{/link} und die Untoten mehr gelitten als jedes andere Volk, und sie sind noch nicht zerbrochen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[In alten Tagen lebten die Menschen als verstreute Stämme im Norden, jeder den anderen misstrauend. Allein der Stamm der {link:arathi-highlands}Arathi{/link} sah, dass das Reich der {link:trolls}Trolle{/link} der Amani sie einen nach dem anderen vernichten würde. Ihr Kriegsherr {link:thoradin}Thoradin{/link} einte die Stämme durch Stärke und Überzeugung, und auf ihre Einheit gründete er die Nation {link:arathor}Arathor{/link} und ihre Festungsstadt {link:stromgarde-keep}Strom{/link}. Als die Amani gegen die {link:high-elves}Hochelfen{/link} von {link:quel-thalas}Quel'Thalas{/link} zogen, folgte Arathor dem Ruf der Elfen. Die Elfen lehrten hundert Menschen die Wege der {link:arcane-magic}arkanen Magie{/link}, und gemeinsam zerschlugen die beiden Völker die Amani in den {link:troll-wars}Trollkriegen{/link}.

Im langen Frieden, der folgte, verblasste die Einheit Arathors. Sein Volk breitete sich über das Land aus und gründete neue Reiche: {link:lordaeron}Lordaeron{/link} im Norden, {link:gilneas}Gilneas{/link} und {link:kul-tiras}Kul Tiras{/link} an den westlichen Küsten, {link:alterac-mountains}Alterac{/link} und Stromgarde in den Bergen, {link:city-of-dalaran}die Stadt der Magier{/link} in {link:dalaran}Dalaran{/link} und im fernen Süden das Königreich {link:azeroth}Azeroth{/link}, das man heute das {link:kingdom-of-stormwind}Königreich Stormwind{/link} nennt.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Die Menschen sind ein Volk von Königen und von Bauern. Ihre Adligen pflegen alte Häuser und ältere Fehden, und ihr gemeines Volk bestellt das Land und denkt kaum an beides. Die Kirche des Heiligen Lichts eint viele von ihnen, und ihre Priester finden sich in jedem Dorf. Die Menschen schätzen Eide, Mut und Pflicht, auch wenn sie sich nicht immer daran halten. Ihre größte Gabe ist, dass sie wieder aufbauen. Was auch immer verbrannt wird, sie errichten es von Neuem.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Königreiche der Menschen sind Schatten ihres früheren Glanzes. Die {link:scourge}Geißel{/link} hält die Ruinen Lordaerons, und der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} führt im Norden seinen eigenen gnadenlosen Krieg. {link:gilneas}Gilneas{/link} hat sich hinter seiner großen Mauer abgeschottet. {link:alterac-mountains}Alterac{/link} liegt in Trümmern, und {link:stromgarde-keep}Stromgarde{/link} klammert sich an das, was vom {link:arathi-highlands}Arathihochland{/link} übrig ist. Im Süden steht {link:stormwind-city}Stormwind{/link} wiederaufgebaut, doch König {link:varian-wrynn}Varian Wrynn{/link} ist verschwunden, und Hochlord {link:bolvar-fordragon}Bolvar Fordragon{/link} herrscht in seinem Namen. Jenseits des Meeres hält Lady {link:jaina-proudmoore}Jaina Proudmoore{/link} die Inselfestung {link:theramore-isle}Theramore{/link}, wo die Menschen einen unruhigen Frieden mit der {link:horde}Horde{/link} wahren. Die Menschheit bleibt das Herz der {link:alliance}Allianz{/link}, und es ist ein Herz, das blutet.]=],
		},
	},
})

Translate("deDE", "dwarves", {
	title = "Zwerge",
	aliases = { "Zwerg" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Zwerge sind ein stämmiges und zähes Volk aus den Bergen von Khaz Modan. Sie sind Bergleute, Schmiede, Brauer und Krieger, und sie gehören zu den besten Handwerkern der Welt. Ihre große Stadt {link:ironforge}Ironforge{/link} ist in das Herz eines Berges gehauen. Seit dem {link:second-war}Zweiten Krieg{/link} kämpfen sie an der Seite der {link:humans}Menschen{/link}, und sie bleiben eine der Säulen der {link:alliance}Allianz{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Zeitalter lang lebten die Zwerge unter den Bergen, und ihre eigenen Legenden besagten, sie seien aus Stein geformt. In den Hallen von {link:uldaman}Uldaman{/link} haben Gelehrte der {link:explorers-league}Forscherliga{/link} Aufzeichnungen der Titanen gefunden, die dies zu bestätigen scheinen: Sie sprechen von den Irdenen, Wesen aus lebendem Fels, von den Titanen geschaffen, um die tiefen Orte der Welt zu formen. Viele Zwerge glauben heute, dass ihr Volk von ihnen abstammt.

Die Zwerge waren lange unter einem einzigen Hochkönig in {link:ironforge}Ironforge{/link} vereint. Als dieser König starb, zogen drei große Klans um seinen Thron in den Krieg. In diesem Krieg der drei Hämmer hielt der Klan Bronzebeard Ironforge. Der Wildhammerklan wurde nach Norden vertrieben und fand mit der Zeit seine Heimat im {link:the-hinterlands}Hinterland{/link}. Der Klan Dark Iron wurde in den Süden verstoßen. Dort suchte sein Zauberkönig {link:ruins-of-thaurissan}Thaurissan{/link} nach einer Macht, um seine Niederlage zu rächen, und er rief {red:ragnaros}Ragnaros{/red} den Feuerfürsten herbei. Das Feuer dieser Beschwörung zerbrach das Land und band die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} an den Dienst des Feuerfürsten.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Zwerge sind stolz, treu und vergeben nur langsam. Sie lieben gutes Bier, lauten Gesang und eine gut gemachte Axt. Sie achten Taten mehr als Worte und sind für ihr langes Gedächtnis bekannt. Ihre Büchsenmacher sind in den ganzen Östlichen Königreichen berühmt, und ihre Gewehre und Kanonen haben viele Mauern gehalten. Die Wildhammer sind wilder als ihre Verwandten und reiten auf Greifen in die Schlacht, während die Bronzebeards die Schmiede und das Gewehr vorziehen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[König {link:magni-bronzebeard}Magni Bronzebeard{/link} herrscht in {link:ironforge}Ironforge{/link}. Sein Bruder {link:brann-bronzebeard}Brann Bronzebeard{/link} führt die {link:explorers-league}Forscherliga{/link}, deren Gräber auf der ganzen Welt Ruinen durchwühlen, auf der Suche nach der wahren Vergangenheit der Zwerge. Ironforge hat seine Tore den {link:gnomes}Gnomen{/link} geöffnet, die ihre Stadt an die {link:troggs}Troggs{/link} verloren, und in {link:tinker-town}Tinker Town{/link} erklingt nun gnomische Arbeit. Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} bleiben die erbittertsten Feinde ihrer Vettern, und in den Tiefen des {link:blackrock-mountain}Blackrock{/link} mühen sie sich im Dienst des Feuerfürsten. Die Wildhammer gehen im {link:the-hinterlands}Hinterland{/link} ihre eigenen Wege, Verbündete Ironforges, doch niemals seine Untertanen.]=],
		},
	},
})

Translate("deDE", "gnomes", {
	title = "Gnome",
	aliases = { "Gnom" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Gnome sind ein kleines, kluges und unendlich neugieriges Volk. Sie sind die größten Tüftler und Ingenieure der Welt, und in allem, was ihnen begegnet, sehen sie ein Problem, das es zu lösen gilt. Über Generationen lebten sie in der wundersamen Stadt {link:gnomeregan}Gnomeregan{/link} in den Bergen von {link:dun-morogh}Dun Morogh{/link}. Diese Stadt ist ihnen nun verloren, und sie leben als Gäste der {link:dwarves}Zwerge{/link} in {link:ironforge}Ironforge{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Gnome sind seit Langem Nachbarn und Freunde der {link:dwarves}Zwerge{/link} von Khaz Modan. Über ihre frühesten Tage sagen die Geschichtsbücher Azeroths wenig. Gewiss ist, dass sie {link:gnomeregan}Gnomeregan{/link} mit eigenen Händen erbauten und mit Wundern füllten: großen Maschinen, Uhrwerkdienern und Geräten, die sich kein anderes Volk hätte ausdenken können. Im {link:second-war}Zweiten Krieg{/link} schlossen sie sich an der Seite der Zwerge der {link:alliance}Allianz{/link} an. Sie schickten wenige Soldaten, denn sie sind kein zahlreiches Volk, doch sie gaben der Allianz Flugmaschinen, Unterseeboote und Waffen eigener Bauart.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Gnome sind aufgeweckt, flink und selbst in den finstersten Stunden fröhlich. Sie lassen sich auch leicht ablenken, und ihre Erfindungen tun nicht immer, was ihre Schöpfer beabsichtigten. Sie schätzen Klugheit über Stärke, und ihre Meisteringenieure halten sie in höchsten Ehren. Ihr Anführer trägt den Titel Hochtüftler. Viele Gnome studieren auch die {link:arcane-magic}arkane Magie{/link}, und manche wenden sich dunkleren Künsten zu, die andere lieber unberührt ließen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Nach dem {link:third-war}Dritten Krieg{/link} stiegen die {link:troggs}Troggs{/link} aus der Tiefe der Erde empor und strömten nach {link:gnomeregan}Gnomeregan{/link}. Die Stadt war nicht zu halten. Der Hochtüftler {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} traf eine verzweifelte Entscheidung und entfesselte eine giftige Waffe, um die Eindringlinge zu vertreiben. Sie tötete viele Troggs, doch sie tötete auch sehr viele Gnome, und sie ließ die Stadt vergiftet zurück. Die Überlebenden flohen nach {link:ironforge}Ironforge{/link}. Nun wird geflüstert, dass der Fall kein Unglück war: Der eigene Berater des Hochtüftlers, {link:mekgineer-thermaplugg}Sicco Thermaplugg{/link}, soll sein Volk verraten haben, und er beherrscht nun die zerstörte Stadt als ihr wahnsinniger Herr. Die Gnome träumen von dem Tag, an dem sie ihre Heimat zurückerobern. Bis dahin tüfteln sie in Ironforge und dienen der {link:alliance}Allianz{/link} mit demselben Eifer, den sie immer gezeigt haben.]=],
		},
	},
})

Translate("deDE", "night-elves", {
	title = "Nachtelfen",
	aliases = { "kaldorei", "kal'dorei", "Nachtelf" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Nachtelfen, die sich selbst kaldorei oder „Kinder der Sterne“ nennen, sind das älteste zivilisierte Volk von {link:kalimdor}Kalimdor{/link}. Sie sind groß, violetthäutig und langlebig, und sie haben die Wälder des Nordens zehntausend Jahre lang bewacht. Ihre Priesterinnen dienen der Mondgöttin Elune, und ihre Druiden pflegen die Wildnis nach den Wegen, die der Halbgott {link:cenarius}Cenarius{/link} lehrte. Nach dem {link:third-war}Dritten Krieg{/link} schlossen sie sich zum ersten Mal in ihrer Geschichte der {link:alliance}Allianz{/link} an.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die ersten Nachtelfen waren ein Stamm, der sich in alter Zeit an den Ufern des {link:well-of-eternity}Brunnens der Ewigkeit{/link} niederließ. Die Macht des Brunnens veränderte sie und schenkte ihnen langes Leben. An seinen Ufern errichteten sie ein großes Reich, beherrscht von {link:queen-azshara}Königin Azshara{/link} und ihrer Kaste hochgeborener Zauberer. Die Hochgeborenen berauschten sich an der Macht des Brunnens, und schließlich lenkte ihre Magie den Blick der {link:burning-legion}Brennenden Legion{/link} auf sich. {link:azshara}Azshara{/link} öffnete den Dämonen den Weg, und der {link:war-of-the-ancients}Krieg der Ahnen{/link} begann.

Der Druide {link:malfurion-stormrage}Malfurion Stormrage{/link}, die Priesterin {link:tyrande-whisperwind}Tyrande Whisperwind{/link} und ihre Verbündeten trieben die Legion zurück. Am Ende wurde der Brunnen zerstört, und die {link:great-sundering}Große Teilung{/link} zerschmetterte den alten Kontinent. Die Nachtelfen, die überlebten, wandten sich von der arkanen Magie ab. Auf dem {link:mount-hyjal}Berg Hyjal{/link} pflegten sie einen neuen Baum des Lebens, {link:nordrassil}Nordrassil{/link}, der ihnen Unsterblichkeit gewährte. Die Hochgeborenen, die ihre Magie nicht aufgeben wollten, wurden über das Meer in die Verbannung geschickt.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Die Nachtelfen sind ein geduldiges und wachsames Volk. Ihre Frauen dienten lange als {link:sentinels}Schildwachen{/link}, die Kriegerinnen, die die Wälder bewachen, während ihre Männer Druiden wurden, die lange Jahre im {link:emerald-dream}Smaragdgrünen Traum{/link} schliefen. Sie lieben die wilden Orte der Welt und hassen jene, die sie verwüsten. Dem Arkanen trauen sie nicht, denn es hätte ihre Welt beinahe beendet.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Im Dritten Krieg kehrte die Legion zurück. In der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} standen Nachtelfen, {link:humans}Menschen{/link} und {link:orcs}Orcs{/link} gemeinsam gegen {link:archimonde}Archimonde{/link}, und Nordrassils Macht wurde aufgezehrt, um ihn zu vernichten. Damit verloren die Nachtelfen ihre Unsterblichkeit. Erzdruide {link:fandral-staghelm}Fandral Staghelm{/link} und seine Druiden ließen daraufhin vor der Nordküste einen neuen Weltenbaum wachsen, {link:teldrassil}Teldrassil{/link}, und in seinen Ästen wuchs die Stadt {link:darnassus}Darnassus{/link}. {link:tyrande-whisperwind}Tyrande{/link} herrscht dort als Hohepriesterin, während {link:malfurion-stormrage}Malfurion{/link} im Smaragdgrünen Traum wandelt und nicht zurückgekehrt ist. Die kaldorei stehen nun den Orcs gegenüber, die die Wälder des {link:ashenvale}Eschentals{/link} roden, und der Verderbnis, die sich im {link:felwood}Teufelswald{/link} ausbreitet.]=],
		},
	},
})

Translate("deDE", "orcs", {
	title = "Orcs",
	aliases = { "Orc" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Orcs sind ein stolzes Kriegervolk von der Welt Draenor. Sie kamen als Eroberer durch das {link:dark-portal}Dunkle Portal{/link} nach {link:azeroth}Azeroth{/link}, und sie brachten Feuer und Verderben über die Königreiche der {link:humans}Menschen{/link}. Sie wurden besiegt, eingekerkert und gebrochen, und doch erhoben sie sich wieder. Unter ihrem Kriegshäuptling {link:thrall}Thrall{/link} haben sie das Meer nach {link:kalimdor}Kalimdor{/link} überquert und in {link:durotar}Durotar{/link} eine neue Heimat errichtet. Sie sind das Herz der {link:horde}Horde{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Auf Draenor lebten die Orcs in vielen Klans. Sie waren Jäger und Krieger, geführt von Schamanen, die mit den Geistern der {link:elements}Elemente{/link} sprachen. Der Dämonenfürst {link:kil-jaeden}Kil'jaeden{/link} machte sich daran, sie zu einer Waffe der {link:burning-legion}Brennenden Legion{/link} zu schmieden. Er täuschte den Ältesten Schamanen {link:ner-zhul}Ner'zhul{/link} und nach ihm Ner'zhuls Schüler {link:gul-dan}Gul'dan{/link}. Gul'dan lehrte die Klans die Künste der Hexenmeister, und die Elemente wandten sich von den Orcs ab. Schließlich tranken die Häuptlinge das Blut des Dämons {link:mannoroth}Mannoroth{/link}, und ein Blutrausch ergriff das ganze Volk.

Durch das Dunkle Portal fiel die {link:horde}Horde{/link} über das Königreich {link:azeroth}Azeroth{/link} her. Sie gewann den {link:first-war}Ersten Krieg{/link} und brannte {link:stormwind-city}Stormwind{/link} nieder. Unter {link:orgrim-doomhammer}Orgrim Doomhammer{/link} hätte sie beinahe auch den {link:second-war}Zweiten Krieg{/link} gewonnen, doch sie wurde von innen verraten und besiegt. Die überlebenden Orcs wurden in {link:internment-camps}Internierungslager{/link} getrieben, wo sich eine seltsame Lethargie über sie legte.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Die Orcs ehren Stärke, Mut und Treue zum Klan. Sie achten den Schamanen, der für die Geister spricht, und den Krieger, der in der Schlacht standhält. Ihre Namen sind stolz, und ebenso ihr Gedächtnis: Jeder Klan bewahrt seine eigenen Legenden und seinen eigenen Groll. Seit dem Ende des Fluchs des Dämons sind viele Orcs zu den alten Wegen des Schamanen zurückgekehrt und suchen das Gleichgewicht mit den Elementen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der junge Orc {link:thrall}Thrall{/link}, als Sklave in einer Festung der {link:humans}Menschen{/link} aufgezogen, entkam seinen Herren und befreite sein Volk aus den {link:camping}Lagern{/link}. Auf den Ruf eines Propheten hin führte er es nach Westen nach {link:kalimdor}Kalimdor{/link}. Dort erschlug {link:grom-hellscream}Grom Hellscream{/link} im {link:third-war}Dritten Krieg{/link} {link:mannoroth}Mannoroth{/link} und befreite die Orcs vom Blut des Dämons. Thrall benannte sein neues Land nach seinem Vater Durotan {link:durotar}Durotar{/link} und seine {link:capital-city}Hauptstadt{/link} {link:orgrimmar}Orgrimmar{/link} nach Doomhammer. Die Orcs wahren nun einen unruhigen Frieden mit {link:theramore-isle}Theramore{/link}. Doch nicht alle Orcs haben sich von der alten Finsternis abgewandt. Der Kult der {link:burning-blade}Brennenden Klinge{/link} flüstert in den Höhlen Durotars, und in den Östlichen Königreichen dient der Klan {link:blackrock-mountain}Blackrock{/link} noch immer den schwarzen Drachen im Blackrock.]=],
		},
	},
})

Translate("deDE", "trolls", {
	title = "Trolle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Trolle gehören zu den ältesten Völkern von {link:azeroth}Azeroth{/link}. Sie sind groß, mit Hauern bewehrt und wild, und ihre Körper heilen Wunden, die jedes andere Geschöpf töten würden. Lange bevor die {link:night-elves}Nachtelfen{/link} ihr Reich errichteten, herrschten die Trolle über eigene große Reiche. Diese Reiche sind gefallen, und die verbliebenen Stämme sind verbittert, zerstritten und gefährlich. Einer von ihnen, der Stamm der {link:darkspear-trolls}Darkspear{/link}, steht nun an der Seite der {link:horde}Horde{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Das älteste Trollkönigreich war das der Zandalari, deren Stamm weit im Süden lebte. Aus ihnen gingen die beiden großen Reiche der alten Zeit hervor: die Amani in den nördlichen Wäldern und die Gurubashi in den südlichen Dschungeln. Sie verehrten mächtige Geister, die Loa genannt werden, und sie führten Krieg gegen die frühen {link:night-elves}Nachtelfen{/link} und verloren. Die {link:great-sundering}Große Teilung{/link} riss ihre Lande auseinander.

Die Amani vergaben den {link:high-elves}Hochelfen{/link} nie, die sich in ihren Wäldern niederließen. In den {link:troll-wars}Trollkriegen{/link} hätten sie {link:quel-thalas}Quel'Thalas{/link} beinahe vernichtet, bis sich die {link:humans}Menschen{/link} von {link:arathor}Arathor{/link} den Elfen anschlossen und sie zerschlugen. Im Süden verfielen die Gurubashi in einen Bürgerkrieg, als die Priester der Atal'ai {link:hakkar}Hakkar{/link}, den Blutgott, herbeiriefen. Die Stämme stürzten den Gott und trieben die Atal'ai in die Sümpfe, wo diese den {link:temple-of-atal-hakkar}Tempel von Atal'Hakkar{/link} erbauten. Ihr Reich erholte sich nie.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Trolle sind Jäger und Plünderer. Ihre Priester üben Voodoo aus und sprechen mit den Loa, und ihre Hexendoktoren brauen Tränke und Flüche, die andere Völker fürchten. Viele Stämme halten an grausamen Bräuchen fest, und von manchen heißt es, dass sie ihre Feinde essen. Sie sind stolz auf ihre alte Vergangenheit und grollen den jüngeren Völkern, die ihnen ihre Lande nahmen. Wenige Trolle trauen Fremden, und noch weniger wird im Gegenzug getraut.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der {link:darkspear-trolls}Stamm der Darkspear{/link} wurde aus seiner Heimat in den Dschungeln vertrieben und fand Zuflucht in den südlichen Meeren. Dort rettete {link:thrall}Thrall{/link} sie vor den {link:humans}Menschen{/link} und der Meerhexe, und ihr Anführer {link:sen-jin-village}Sen'jin{/link} gab sein Leben, damit sein Volk den {link:orcs}Orcs{/link} folgen konnte. Heute dienen die Darkspear der {link:horde}Horde{/link} unter {link:vol-jin}Vol'jin{/link}. Sie siedelten sich auf den Echoinseln vor {link:durotar}Durotar{/link} an, doch ein Hexendoktor namens {link:zalazane}Zalazane{/link} hat die Inseln mit dunkler Magie an sich gerissen, und der Stamm hat sich nach Sen'jin auf dem Festland zurückgezogen. Anderswo bleiben die Trollstämme Feinde aller: die Amani in den nördlichen Wäldern, die {link:witherbark-village}Witherbark{/link} und Vilebranch im {link:the-hinterlands}Hinterland{/link}, die Stämme der Gurubashi im {link:stranglethorn-vale}Schlingendorntal{/link}, die {link:sandfury-trolls}Sandfury{/link} in {link:tanaris}Tanaris{/link} und die {link:frostmane-trolls}Frostmane{/link} in {link:dun-morogh}Dun Morogh{/link}.]=],
		},
	},
})

Translate("deDE", "tauren", {
	title = "Tauren",
	aliases = { "Tauren", "shu'halo" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Tauren sind ein Volk von großer Gestalt und sanfter Weisheit, das durch die Ebenen von {link:kalimdor}Kalimdor{/link} zieht. Sie sind gewaltig und stierähnlich, und sie können in der Schlacht furchtbar sein, doch sie leben lieber in Frieden mit dem Land. Sie verehren die Erdmutter über alles. Unter ihrem großen Häuptling {link:cairne-bloodhoof}Cairne Bloodhoof{/link} haben sie sich im Grasland von {link:mulgore}Mulgore{/link} niedergelassen und sich der {link:horde}Horde{/link} angeschlossen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Tauren, die sich selbst shu'halo nennen, gehören zu den ältesten Völkern Kalimdors. Zeitalter lang zogen sie als Nomaden durch die Ebenen und folgten den großen Herden und dem Wechsel der Jahreszeiten. Sie sagen, dass die Erdmutter ihnen das Land gab und dass Sonne und Mond ihre Augen sind, die sie An'she und Mu'sha nennen. Die Stämme lebten getrennt, jeder mit seinen eigenen Häuptlingen und seinen eigenen Totems.

Dieses Leben wurde von den {link:centaurs}Zentauren{/link} beinahe beendet. Die grausamen Pferdemenschen der Ebenen jagten die verstreuten Stämme über Generationen und vertrieben sie von den Landen ihrer Ahnen. {link:cairne-bloodhoof}Cairne Bloodhoof{/link} machte es sich zur Aufgabe, die Stämme gegen sie zu einen. Als die {link:orcs}Orcs{/link} nach {link:kalimdor}Kalimdor{/link} kamen, traf Cairne den jungen {link:thrall}Thrall{/link}, und die beiden Völker erkannten einander als Geistesverwandte. Mit der Hilfe der Orcs brachen die Tauren die Herrschaft der Zentauren über {link:mulgore}Mulgore{/link} und beanspruchten es als ihre Heimat.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Die Tauren leben eng mit dem Land. Sie jagen mit Achtung und nehmen nur, was sie brauchen. Ihre Schamanen sprechen mit den Geistern der {link:elements}Elemente{/link} und ihrer Ahnen, und manche Tauren haben die Wege des Druiden erlernt, ausgebildet von den {link:night-elves}Nachtelfen{/link} des {link:cenarion-circle}Zirkels des Cenarius{/link}. Sie sind geduldig, langsam zum Zorn und ehrlich bis zum Übermaß. Ihre Totems verzeichnen die Abstammung und die Taten ihrer Stämme.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Tauren haben ihre {link:capital-city}Hauptstadt{/link} {link:thunder-bluff}Thunder Bluff{/link} auf hohen Tafelbergen über {link:mulgore}Mulgore{/link} erbaut, erreichbar über große Aufzüge. {link:cairne-bloodhoof}Cairne{/link} herrscht dort als Hochhäuptling, geachtet selbst von jenen, die die {link:horde}Horde{/link} fürchten. Nicht alle Stämme teilen seine Vision. Der Stamm der Grimtotem, geführt von der alten Vettel {link:magatha-grimtotem}Magatha{/link}, verfolgt eigene Ziele, und viele in Thunder Bluff trauen ihm wenig. Rund um Mulgore stehen die Tauren noch immer Feinden gegenüber: den Stachelebern vom Stamm der {link:bristleback-quilboar}Borstennacken{/link}, den {link:harpies}Harpyien{/link} der Grate und den {link:centaurs}Zentauren{/link} im {link:the-barrens}Brachland{/link}. Die Tauren ehren ihre Schuld gegenüber den {link:orcs}Orcs{/link}, und sie gehören zu den standhaftesten Mitgliedern der Horde.]=],
		},
	},
})

Translate("deDE", "forsaken", {
	title = "Verlassene",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Verlassenen sind Untote, die sich vom Willen des Lichkönigs befreit haben. Einst waren sie das Volk von {link:lordaeron}Lordaeron{/link}. Sie starben an der Seuche, erhoben sich als Sklaven der {link:scourge}Geißel{/link} und erwachten dann, in einer einzigen Stunde, in der der Griff ihres Meisters schwach wurde, wieder zu eigenem Verstand. Sie folgen {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, der Bansheekönigin, und sie haben unter den Ruinen ihrer alten {link:capital-city}Hauptstadt{/link} ein finsteres Königreich geschaffen. Aus eigenen Gründen haben sie sich der {link:horde}Horde{/link} angeschlossen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Im {link:third-war}Dritten Krieg{/link} fegte die Seuche des {link:cult-of-the-damned}Kults der Verdammten{/link} über {link:lordaeron}Lordaeron{/link}, und Prinz {link:arthas-menethil}Arthas Menethil{/link} ermordete seinen Vater {link:terenas-menethil}Terenas Menethil{/link} und übergab das Königreich der {link:scourge}Geißel{/link}. Tausende, die starben, erhoben sich wieder im Dienst des Lichkönigs. Eine Zeit lang hatten sie überhaupt keinen Willen.

Dann geriet die Macht des Lichkönigs ins Wanken, und viele der Untoten in Lordaeron stellten fest, dass sie wieder selbst denken konnten. {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, die gefallene Waldläufergeneralin von {link:quel-thalas}Quel'Thalas{/link}, war von Arthas selbst als Banshee erweckt worden. Mit ihnen riss sie sich los. Sie wandte sich gegen die Schreckenslords, die das zerstörte Königreich beherrschen wollten, und band einen von ihnen, {link:varimathras}Varimathras{/link}, an ihren Dienst. Sie nannte ihr Volk die Verlassenen, und sie führte sie, um die Ruinen der {link:capital-city}Hauptstadt{/link} Lordaerons für sich einzunehmen.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Die Verlassenen erinnern sich an ihr Leben, doch sie können nicht dorthin zurückkehren. Ihre Freunde und Verwandten fürchten und hassen sie, und viele von ihnen haben gelernt, im Gegenzug zu hassen. Sie sind grimmig, verbittert und praktisch. Ihre Gelehrten betreiben jede Kunst der Alchemie und der Nekromantie ohne Scham, und ihre Priester haben sich vom {link:holy-light}Heiligen Licht{/link} ab- und dem Schatten zugewandt. Unter den Lebenden werden sie eher geduldet als vertraut.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Unter der zerschmetterten {link:capital-city}Stadt Lordaeron{/link} haben die Verlassenen die {link:undercity}Undercity{/link} errichtet, ein Labyrinth aus Hallen und Abwasserkanälen, erbaut in den alten königlichen Grüften. Von dort aus beherrscht {link:sylvanas-windrunner}Sylvanas{/link} {link:tirisfal-glades}Tirisfal{/link} und führt Krieg an zwei Fronten: gegen die {link:scourge}Geißel{/link}, die noch immer die Pestländer hält, und gegen den {link:scarlet-crusade}Scharlachroten Kreuzzug{/link}, der jeden Untoten verbrennt, den er findet. Ihr Bündnis mit der {link:horde}Horde{/link} ist eines der Not. Die {link:orcs}Orcs{/link} und {link:tauren}Tauren{/link} finden sie fremd und beunruhigend. Die Verlassenen ihrerseits sagen wenig über ihre wahren Ziele, und die Chemiker der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link} arbeiten im Geheimen an einer neuen Seuche.]=],
		},
	},
})

Translate("deDE", "skyborne", {
	title = "Skyborne",
	aliases = { "shen'dorei" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Skyborne, die sich selbst shen'dorei oder „verborgenes Volk“ nennen, sind Elfen, die seit Tausenden von Jahren jenseits der Welt selbst leben. Ihre Heimat ist {link:zephras-isle}Zephras Isle{/link}, eine Insel, die in {link:skywall}Skywall{/link} schwebt, der Elementarebene der Luft. Sie teilen das Blut der Hochgeborenen, und sie sind Vettern der {link:high-elves}Hochelfen{/link} von {link:quel-thalas}Quel'Thalas{/link}. Nun versagt ihr Reich im Himmel, und eine neue Generation der Skyborne ist nach {link:azeroth}Azeroth{/link} herabgekommen, auf der Suche nach Antworten.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Skyborne führen ihre Abstammung auf die Hochgeborenen von Eldre'Thalas zurück, der Stadt in {link:feralas}Feralas{/link}, die heute {red:dire-maul}Düsterbruch{/red} heißt. Nach dem {link:war-of-the-ancients}Krieg der Ahnen{/link} versuchte Prinz {red:tortheldrin}Tortheldrin{/red}, die Stadt mit immer gefährlicheren Mächten zu erhalten. Manche seines Volkes hatten gesehen, was solcher Hunger nach Macht der Welt angetan hatte, und sie erhoben sich gegen ihn. Sie vereitelten seine Pläne, doch ihre Rebellion wurde niedergeschlagen, und sie flohen über das Meer, die Flotte des Prinzen dicht auf den Fersen.

Weit im Westen stießen sie auf ein Land, das von uralten Geistern der {link:elements}Elemente{/link} beherrscht wurde. Dort schlossen sie einen Pakt mit den Geistern des Windes. Die Geister rissen einen großen Teil dieses Landes in den Himmel, trugen ihn aus der Welt hinaus und verankerten ihn in {link:skywall}Skywall{/link}. Verborgen vor ihren Verfolgern errichteten die Verbannten eine kleine, strahlende Zivilisation zwischen den Wolken.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Die langen Zeitalter in {link:skywall}Skywall{/link} veränderten die shen'dorei. Sie wurden leichter und schneller als ihre Vorfahren, und die Magie der Luft zeichnete ihr Haar, ihre Augen und ihre Haut. Sie lebten neben den Windgeistern als deren Schüler und Freunde. Manche unter ihnen empfingen die Gabe der Geister, die Himmelssicht, die Macht, über die Elementarebene hinwegzusehen. Die Geister sprachen selten von {link:al-akir}Al'Akir{/link} dem Windfürsten, dem Herrn von Skywall, und unter den Skyborne wurde sein Name zu etwas, das Furcht und Schweigen hervorrief.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Ohne Vorwarnung verschwanden die {link:vanishing-of-the-wind-spirits}Windgeister{/link}. Die uralten Pylonen, die {link:zephras-isle}Zephras Isle{/link} zusammenhalten, haben zu versagen begonnen, Teile der Insel sind verfallen, und ihre Gemeinschaften sind voneinander abgeschnitten. Die Skyborne sind uneins darüber, was zu tun ist.

• {b}Die {link:windshapers}Windshapers{/link}.{/b} Sie stammen von den ersten shen'dorei ab, die die Himmelssicht empfingen, und sie sind die geistlichen Führer der Insel. Sie suchen zu erfahren, was aus den Windgeistern geworden ist, und sie wiederherzustellen. Sie haben sich der {link:horde}Horde{/link} angeschlossen.
• {b}Der {link:high-order}High Order{/link}.{/b} Sie stammen von den hochgeborenen Magistern ab, die aus Eldre'Thalas flohen, und sie glauben, dass die Skyborne ihren Schutzherren zu sehr vertrauten. Sie suchen das arkane Wissen, das ihre Vorfahren verloren, damit ihr Volk auf eigenen Füßen stehen kann. Sie haben sich der {link:alliance}Allianz{/link} angeschlossen.
• {b}Die {link:al-aketh}Al'Aketh{/link}.{/b} Ein Kult, der sich von den übrigen shen'dorei abwandte, um {link:al-akir}Al'Akir{/link} zu dienen. Ermutigt durch die Abwesenheit der Geister haben sie Furcht verbreitet und einen großen Teil der Insel an sich gerissen.]=],
		},
	},
})

Translate("deDE", "high-elves", {
	title = "Hochelfen",
	aliases = { "quel'dorei", "Hochelf" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Hochelfen oder quel'dorei sind die Kinder der verbannten Hochgeborenen, die nach der {link:great-sundering}Großen Teilung{/link} das Meer überquerten. In den Wäldern des nördlichen {link:lordaeron}Lordaeron{/link} errichteten sie das Königreich {link:quel-thalas}Quel'Thalas{/link} und seine strahlende {link:capital-city}Hauptstadt{/link} Silbermond. Tausende von Jahren waren sie die Meister der {link:arcane-magic}arkanen Magie{/link} in den {link:eastern-kingdoms}Östlichen Königreichen{/link}. Im {link:third-war}Dritten Krieg{/link} wurde ihr Königreich beinahe vernichtet.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Nach der Teilung verboten die {link:night-elves}Nachtelfen{/link} den Gebrauch arkaner Magie. Die Hochgeborenen, die nicht gehorchen wollten, geführt von {red:dath-remar-sunstrider}Dath'Remar Sunstrider{/red}, wurden verbannt. Sie segelten nach Osten und kamen nach langer Wanderschaft in die nördlichen Wälder, wo sie gegen die {link:trolls}Trolle{/link} der Amani um ihre neue Heimat kämpften. Dort erschufen sie den Sonnenbrunnen, einen Quell arkaner Macht, der ihr Volk erhielt. Als sich die Amani gegen sie erhoben, verbündeten sie sich mit den {link:humans}Menschen{/link} von {link:arathor}Arathor{/link} und lehrten sie Magie, und gemeinsam gewannen sie die {link:troll-wars}Trollkriege{/link}.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Die Hochelfen sind anmutig, stolz und gelehrt. Sie lieben Schönheit und Magie, und viele von ihnen blicken auf die jüngeren Völker herab. Ihre Waldläufer sind die besten Bogenschützen des Nordens. Ihre Bindung an den Sonnenbrunnen reichte so tief, dass sie von seiner Macht abhängig wurden.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Im Dritten Krieg führte {link:arthas-menethil}Arthas Menethil{/link} die {link:scourge}Geißel{/link} nach {link:quel-thalas}Quel'Thalas{/link}. Er erschlug König Anasterian Sunstrider und nutzte den Sonnenbrunnen, um den Lich {link:kel-thuzad}Kel'Thuzad{/link} zu erwecken. Waldläufergeneralin {link:sylvanas-windrunner}Sylvanas Windrunner{/link} fiel bei der Verteidigung ihrer Heimat. Die wenigen, die überlebten, sind verstreut: Manche halten noch, was von Quel'Thalas übrig ist, manche dienen der {link:alliance}Allianz{/link} und der {link:kirin-tor}Kirin Tor{/link}, und eine kleine Schar hält die Jagdhütte von {link:quel-danil-lodge}Quel'Danil{/link} im {link:the-hinterlands}Hinterland{/link}. Prinz Kael'thas, der Erbe der Sunstriders, sammelte viele der Überlebenden und nannte sie im Gedenken an die Gefallenen sin'dorei, die Blutelfen. Was seither aus ihm geworden ist, kann keine Chronik dieser Lande sagen.]=],
		},
	},
})

Translate("deDE", "kobolds", {
	title = "Kobolde",
	aliases = { "Kobold" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kobolde sind kleine, rattenähnliche Geschöpfe, die in Minen und Höhlen überall in {link:azeroth}Azeroth{/link} hausen. Sie sind feige, gierig und nicht sehr klug, doch es gibt sehr viele von ihnen. Wo immer eine alte Mine unbewacht bleibt, ziehen die Kobolde ein. Jeder trägt eine Kerze auf dem Kopf, um die Stollen zu erhellen, und jeder würde lieber sterben, als sie herzugeben.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, woher die Kobolde ursprünglich kamen. Manche Forscher der {link:explorers-league}Forscherliga{/link} glauben, dass sie von den {link:troggs}Troggs{/link} der tiefen Orte abstammen. Wie auch immer ihre Anfänge waren, sie waren schon den ersten Siedlern von {link:tirisfal-glades}Tirisfal{/link} eine Plage, und seither plagen sie die Bergleute.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Kobolde lieben die dunklen Stollen, fürchten aber die wahre Dunkelheit, und ihre Kerzen sind das Kostbarste, was sie besitzen. Eine zu stehlen ist das schlimmste aller Verbrechen, und der Dieb wird davon zu hören bekommen. Sie graben ohne Ende und horten alles, was glitzert. Ihre Geomanten wirken grobe Magie aus Feuer und Stein. Die meisten kämpfen nur, wenn sie in die Enge getrieben werden, doch in einem Schwarm können sie einen unvorsichtigen Bergmann überwältigen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Kobolde befallen die Minen im {link:elwynn-forest}Wald von Elwynn{/link} und in {link:westfall}Westfall{/link}, wo sie nach Gold graben, das nicht in ihren Händen bleibt. Es heißt, dass sie von den {link:riverpaw-gnolls}Gnollen der Flusspfoten{/link} angetrieben werden, die ihrerseits mit der {link:defias-brotherhood}Bruderschaft der Defias{/link} Geschäfte machen. Die Tunnel Rats bedrängen die {link:dwarves}Zwerge{/link} von {link:loch-modan}Loch Modan{/link}, und in {link:kalimdor}Kalimdor{/link} graben Kobolde für die {link:venture-company}Venture Company{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link}.]=],
		},
	},
})

Translate("deDE", "gnolls", {
	title = "Gnolle",
	aliases = { "Gnoll" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gnolle sind hyänenartige Geschöpfe, die durch die wilden Orte der {link:eastern-kingdoms}Östlichen Königreiche{/link} und {link:kalimdor}Kalimdor{/link}s streifen. Sie sind roh, streitsüchtig und hungrig, und sie schätzen Stärke über alles. Sie leben in Rudeln und Klans, jeweils vom Stärksten unter ihnen beherrscht, und sie überfallen die Höfe und Straßen anderer Völker auf der Suche nach Nahrung und Beute.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Gnolle sind ein altes Volk Azeroths, und keine Chronik verzeichnet ihre Anfänge. Sie gehörten zu den Gefahren, denen sich die ersten menschlichen Siedler im Norden stellen mussten. Das {link:kingdom-of-stormwind}Königreich Stormwind{/link} erinnert sich an eine dunklere Zeit, als ein Rudelführer der {link:redridge-gnolls}Gnolle des Rotkammgebirges{/link} namens Garfang die Klans zu einem großen Heer sammelte und die Höfe des Königreichs angriff. König Barathen Wrynn ritt aus und erschlug ihn, und die Rudel zerfleischten sich im darauffolgenden Kampf selbst.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Gnolle lassen lieber andere ihre Arbeit tun. Ihre Anführer treiben die Schwachen vor sich her, und sie dienen gern jedem stärkeren Herrn, der ihnen Nahrung und Beute verspricht. Ihre Mystiker üben einen groben Schamanismus aus. Sie sind listig genug, Fallen und Hinterhalte zu legen, und grausam genug, sich daran zu erfreuen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Gnolle bedrängen fast jede Grenze der Lande der {link:humans}Menschen{/link}. Die {link:riverpaw-gnolls}Flusspfoten{/link} überfallen den {link:elwynn-forest}Wald von Elwynn{/link} und {link:westfall}Westfall{/link}. Das {link:redridge-gnolls}Rudel des Rotkammgebirges{/link} und die {link:shadowhide-gnolls}Schattenfelle{/link} streifen durch das {link:redridge-mountains}Rotkammgebirge{/link}, Letztere im Bann des Hexenmeisters {link:morganth}Morganth{/link}. Die Moosfelle suchen das {link:wetlands}Sumpfland{/link} heim, die Moderfelle graben in {link:tirisfal-glades}Tirisfal{/link} die Toten für die {link:scourge}Geißel{/link} aus, und andere Klans streifen durch {link:razorfen-downs}die Hügel{/link} von {link:hillsbrad-foothills}Hillsbrad{/link} und die Wälder von {link:feralas}Feralas{/link}.]=],
		},
	},
})

Translate("deDE", "riverpaw-gnolls", {
	title = "Gnolle der Flusspfoten",
	aliases = { "Flusspfoten-Gnolle", "Flusspfoten" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Flusspfoten sind der Gnollklan, der die südlichen Lande des {link:kingdom-of-stormwind}Königreichs Stormwind{/link} plagt. Sie streifen entlang der Grenze des {link:elwynn-forest}Waldes von Elwynn{/link}, durch die Felder von {link:westfall}Westfall{/link} und in Richtung des {link:redridge-mountains}Rotkammgebirges{/link}. Sie überfallen Höfe, lauern Reisenden auf und bekämpfen die wenigen Soldaten, die das Königreich entbehren kann. Der gefürchtetste von ihnen ist der große {link:gnolls}Gnoll{/link} {link:hogger}Hogger{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[Die Flusspfoten sind kühner geworden, seit das Heer des Königreichs in die Ferne geschickt wurde. Sie kommen aus dem Waldrand hervor, um die Höfe im südlichen {link:elwynn-forest}Elwynn{/link} anzugreifen, und die {link:westbrook-garrison}Weststromgarnison{/link} zahlt ein Kopfgeld für jede Pfote, die ihre Freiwilligen zurückbringen. In {link:westfall}Westfall{/link} sind ihre Lager noch größer. Die Volksmiliz hat Anzeichen gefunden, dass die Flusspfoten nicht nur für sich selbst kämpfen: Sie treiben {link:kobolds}Kobold{/link}sklaven in den Minen an, und sie machen Geschäfte mit der {link:defias-brotherhood}Bruderschaft der Defias{/link}. Viele in {link:stormwind-city}Stormwind{/link} fragen sich, wer sie bewaffnet und wer ihnen ihre ungewöhnliche Schläue verleiht.]=],
		},
	},
})

Translate("deDE", "murlocs", {
	title = "Murlocs",
	aliases = { "Murloc" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Murlocs sind kleine, fischähnliche Geschöpfe, die entlang der Küsten, Seen und Flüsse von {link:azeroth}Azeroth{/link} leben. Sie gehen auf zwei Beinen, sprechen eine gurgelnde Sprache, die kein anderes Volk versteht, und greifen in plötzlichen Schwärmen an. Jeder Fischer der {link:eastern-kingdoms}Östlichen Königreiche{/link} und {link:kalimdor}Kalimdor{/link}s hat eine Geschichte über die Murlocs.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, woher die Murlocs kamen. Sie suchen die Küsten der Welt heim, seit irgendein Volk Aufzeichnungen führt, und die Kriege der Landbewohner scheinen sie nicht zu kümmern.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Murlocs leben in Stämmen, in Dörfern aus Hütten, die am Rand des Wassers errichtet sind. Sie jagen Fische und was sonst ihren Ufern zu nahe kommt. Ihre Orakel und Gezeitenjäger wirken eine schlichte Magie aus Wasser und Sturm. Allein sind sie selten gefährlich, doch sie kommen selten allein. Wird ein Murloc angegriffen, tauchen andere mit einem schrecklichen Schrei aus dem seichten Wasser auf.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Murlocs sind kühn geworden, während die Königreiche schwächer werden. Sie überfallen die Seeufer im {link:elwynn-forest}Wald von Elwynn{/link} und die Küste von {link:westfall}Westfall{/link}. Der Stamm der Bluegill sucht die {link:the-marshlands}Marschen{/link} des {link:wetlands}Sumpflands{/link} heim, und der Stamm der Greymist die Ufer der {link:darkshore}Dunkelküste{/link}. An jeder Küste, vom {link:stranglethorn-vale}Schlingendorntal{/link} bis nach {link:durotar}Durotar{/link}, stehen ihre Hütten am Rand des Wassers.]=],
		},
	},
})

Translate("deDE", "quilboar", {
	title = "Stacheleber",
	aliases = { "Stacheleber" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Stacheleber sind ein wildes Volk von Ebermenschen, das im südlichen {link:the-barrens}Brachland{/link} und den umliegenden Landen haust. Sie sind mit Borsten und Dornen bedeckt, und sie errichten ihre Heime zwischen großen, verschlungenen Dornenranken. Sie sind fast jedem anderen Volk feindlich gesinnt, und sie liegen seit Langem im Krieg mit den {link:tauren}Tauren{/link} und den {link:orcs}Orcs{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Stacheleber halten sich für die Kinder von Agamaggan, dem großen Eberhalbgott. Im {link:war-of-the-ancients}Krieg der Ahnen{/link} kämpfte Agamaggan gegen die {link:burning-legion}Brennende Legion{/link} und wurde erschlagen. Wo sein Blut fiel, wuchsen gewaltige Dornenranken aus der Erde. Diese Dornen wurden zum Razorfen, und die Stacheleber machten sie zu ihrer heiligen Heimat.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Die Stacheleber sind wild und verteidigen ihr Gebiet. Ihre Stämme werden von Kriegsherren geführt, und ihre Geomanten rufen die Erde an. Sie verehren das Andenken an Agamaggan und halten den Razorfen heilig. Manche ihrer Priesterinnen haben sich dunkleren Künsten zugewandt, und manche ihrer Krieger dunkleren Herren.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der {link:razormane-quilboar}Stamm der Grimmhauer{/link} überfällt die Ränder von {link:durotar}Durotar{/link} und das nördliche {link:the-barrens}Brachland{/link}, und der Stamm der {link:bristleback-quilboar}Borstennacken{/link} bedrängt die Ebenen von {link:mulgore}Mulgore{/link}. Im Süden hausen die Stacheleber in den großen Dornenbauen des {link:razorfen-kraul}Krals von Razorfen{/link} und der {link:razorfen-downs}Hügel von Razorfen{/link}. Es heißt, dass sich in den Hügeln ein Kult namens {link:death-s-head}Totenkopf{/link} der {link:scourge}Geißel{/link} zugewandt hat und dass nun ein Lich unter ihnen haust.]=],
		},
	},
})

Translate("deDE", "centaurs", {
	title = "Zentauren",
	aliases = { "Zentaur" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Zentauren sind ein grausames und kriegerisches Volk von {link:kalimdor}Kalimdor{/link}. Sie haben den Oberkörper eines Mannes und den Leib eines Pferdes, und sie sind furchtbare Plünderer, die in schnellen, gnadenlosen Scharen reiten. Seit Generationen sind sie die größten Feinde der {link:tauren}Tauren{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Zentauren sollen von der Verbindung Zaetars, eines Sohnes des Halbgottes {link:cenarius}Cenarius{/link}, mit Theradras abstammen, einer Prinzessin der elementaren Erde. Ihre frühesten Kinder waren über alle Maßen grausam, und in einem Anfall von Eifersucht erschlugen sie ihren eigenen Vater. Theradras bettete Zaetar in den Höhlen von {red:maraudon}Maraudon{/red} zur Ruhe, wo sein Geist noch immer verweilen soll.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Die Zentauren leben als Nomaden und Plünderer. Sie sind der Ansicht, dass die Starken sich von den Schwachen nehmen sollen, was sie wollen. Ihre Khane führen die Stämme, und die Stämme bekriegen einander, wenn sie keine anderen Feinde haben. Sie sind geschickte Reiter und Bogenschützen, und sie zeigen wenig Gnade.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der {link:kolkar-centaurs}Stamm der Kolkar{/link} durchstreift das {link:the-barrens}Brachland{/link}, und seine Plünderer greifen die orcischen Außenposten dort an. Die Galak reiten durch {link:thousand-needles}Tausend Nadeln{/link}. In {link:desolace}Desolace{/link} führen die {link:magram-village}Magram{/link} und die {link:gelkis-village}Gelkis{/link} eine lange Fehde, und beide beanspruchen die Gunst der Theradras. Die Maraudine bewachen den Eingang von Maraudon selbst. Obwohl {link:cairne-bloodhoof}Cairne{/link} die Zentauren aus {link:mulgore}Mulgore{/link} vertrieb, haben sie die {link:tauren}Tauren{/link} nicht vergessen.]=],
		},
	},
})

Translate("deDE", "furbolgs", {
	title = "Furbolgs",
	aliases = { "Furbolg" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Furbolgs sind ein bärenähnliches Volk aus den nördlichen Wäldern von {link:kalimdor}Kalimdor{/link}. Lange waren sie ein sanftes und friedliches Volk, Freunde der {link:night-elves}Nachtelfen{/link} und der Druiden. In den letzten Jahren ist eine Krankheit des Geistes über die meisten ihrer Stämme gekommen, und viele Furbolgs sind wild und feindselig geworden.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Furbolgs leben seit alter Zeit in den Wäldern Kalimdors. Einst zählten sie zu den Verbündeten der {link:night-elves}kaldorei{/link}. Keine Chronik verzeichnet ihre Anfänge genauer.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Furbolgs leben in Stämmen, in Bauen und Dörfern tief in den Wäldern verborgen. Ihre Schamanen sind weise in den Wegen des Waldes. Die meisten waren zufrieden, still zu leben und in Frieden mit ihren Nachbarn Handel zu treiben.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die dämonische Verseuchung, die seit dem {link:third-war}Dritten Krieg{/link} in den Wäldern zurückblieb, hat viele Stämme in den Wahnsinn getrieben. Die Thistlefur und Foulweald im {link:ashenvale}Eschental{/link}, die Deadwood im {link:felwood}Teufelswald{/link}, die {link:blackwood-furbolgs}Schwarzfelle{/link} an der {link:darkshore}Dunkelküste{/link}, die Gnarlpine auf {link:teldrassil}Teldrassil{/link} und die {link:winterfall-furbolgs}Winterfall{/link} in {link:winterspring}Winterspring{/link} haben sich gegen ihre alten Freunde gewandt. Nur die {link:timbermaw-furbolgs}Holzschlund{/link} haben der Verderbnis standgehalten. Sie bewachen die Pässe der {link:timbermaw-hold}Holzschlundfeste{/link} und trauen keinem Fremden, bis er sich bewährt hat.]=],
		},
	},
})

Translate("deDE", "harpies", {
	title = "Harpyien",
	aliases = { "Harpyie" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Harpyien sind geflügelte Geschöpfe von {link:kalimdor}Kalimdor{/link}, mit den Leibern von Frauen und den Flügeln und Krallen von Vögeln. Sie sind grausam, listig und bösartig, und sie machen von ihren Nestern an hohen Orten aus Jagd auf Reisende.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Ursprünge der Harpyien sind in keiner Chronik verzeichnet, die diesem Werk bekannt ist.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Harpyien leben in Schwärmen, die von Matriarchinnen beherrscht werden. Sie nisten auf Klippen und Graten und stoßen auf alles herab, was schwächer ist als sie selbst. Sie lieben gestohlene glänzende Dinge und das Fleisch derer, die sie fangen. Ihre Hexen gebieten über dunkle Magie.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die {link:windfury-harpies}Harpyien der Windfurien{/link} nisten auf den Graten von {link:mulgore}Mulgore{/link}, sehr zum Ärger der {link:tauren}Tauren{/link}. Die Witchwing hausen im {link:the-barrens}Brachland{/link}, die Bloodfury im {link:stonetalon-mountains}Steinkrallengebirge{/link} und die Northspring in {link:feralas}Feralas{/link}. Die Straßen Kalimdors sind unter ihren Nestern nicht sicher.]=],
		},
	},
})

Translate("deDE", "troggs", {
	title = "Troggs",
	aliases = { "Trogg" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Troggs sind rohe Geschöpfe mit steinerner Haut, die tief unter der Erde leben. Sie sind stark, dumm und unablässig angriffslustig. Zeitalter lang waren sie in der Tiefe verborgen. Nun sind sie an die Oberfläche gekommen, und sie haben Verderben mitgebracht.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Aufzeichnungen von {link:uldaman}Uldaman{/link} berichten, dass die Troggs wie die Irdenen von den Titanen geschaffen wurden. Sie waren eine fehlerhafte Schöpfung, und die Titanen schlossen sie in den tiefen Gewölben der Welt ein. Die {link:explorers-league}Forscherliga{/link} glaubt, dass die {link:dwarves}Zwerge{/link} diese Gewölbe beim Graben in Uldaman gestört haben und dass sich die Troggs seither ausbreiten.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Troggs leben in Stämmen, die vom Stärksten unter ihnen geführt werden. Ihre Schamanen wirken eine grobe Erdmagie. Sie kümmern sich um wenig außer Kämpfen und Fressen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Troggs stiegen unter {link:gnomeregan}Gnomeregan{/link} empor und vertrieben die {link:gnomes}Gnome{/link} aus ihrer Stadt. Sie bekämpfen die {link:dwarves}Zwerge{/link} in {link:dun-morogh}Dun Morogh{/link} und {link:loch-modan}Loch Modan{/link}, und sie schwärmen durch {link:uldaman}Uldaman{/link} und das {link:badlands}Ödland{/link}. Wo immer die Zwerge tief graben, fürchten sie, noch mehr zu finden.]=],
		},
	},
})

Translate("deDE", "ogres", {
	title = "Oger",
	aliases = { "Oger" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Oger sind riesige, stumpfsinnige Rohlinge von großer Kraft. Manche haben zwei Köpfe, und einige wenige sind listige Zauberer. Die meisten kamen mit den {link:orcs}Orcs{/link} von Draenor nach {link:azeroth}Azeroth{/link}, und viele Klans hausen heute in den wilden Gegenden beider Kontinente.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Oger dienten der orcischen {link:horde}Horde{/link} im {link:second-war}Zweiten Krieg{/link}. Der Hexenmeister {link:gul-dan}Gul'dan{/link} schenkte einigen von ihnen die Gabe der Zauberkunst, und diese Ogermagier wurden in den ganzen {link:eastern-kingdoms}Östlichen Königreichen{/link} gefürchtet. Der größte von ihnen, Cho'gall, führte den Klan des {link:twilight-s-hammer}Schattenhammers{/link}. Nach der Niederlage der Horde zerstreuten sich die Ogerklans in {link:razorfen-downs}die Hügel{/link} und Berge.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Oger sind kriegerisch und gierig. Sie achten nur Stärke und kämpfen untereinander um die Führung. Ihre Häuptlinge herrschen mit der Keule, ihre Magier durch Furcht.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Ogerklans halten {link:razorfen-downs}die Hügel{/link} im {link:redridge-mountains}Rotkammgebirge{/link}, im {link:stranglethorn-vale}Schlingendorntal{/link}, im {link:alterac-mountains}Alteracgebirge{/link} und im {link:arathi-highlands}Arathihochland{/link}. In {link:kalimdor}Kalimdor{/link} suchen die Gordunni {link:feralas}Feralas{/link} heim, und die Gordok beherrschen die Ruinen von {red:dire-maul}Düsterbruch{/red}. In den {link:dustwallow-marsh}Marschen von Dustwallow{/link} hat der Klan der Stonemaul seine alte Stärke verloren, und manche seiner Oger leben nun an der Seite der {link:orcs}Orcs{/link}.]=],
		},
	},
})

Translate("deDE", "naga", {
	title = "Naga",
	aliases = { "Naga" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Naga sind schlangenartige Geschöpfe der tiefen Meere. Einst waren sie {link:night-elves}Nachtelfen{/link} aus der Kaste der Hochgeborenen. Nun haben sie geschuppte Schwänze und grausame Gesichter, und sie sind aus der Tiefe zurückgekehrt, um die Küsten der Welt heimzusuchen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Als der {link:well-of-eternity}Brunnen der Ewigkeit{/link} in der {link:great-sundering}Großen Teilung{/link} zerstört wurde, wurde der Palast von {link:queen-azshara}Königin Azshara{/link} mitsamt ihrem ganzen Hof vom Meer verschlungen. Etwas in der Tiefe rettete sie und veränderte sie. Die ertrunkenen Hochgeborenen wurden zu den Naga. Zehntausend Jahre lang lebten sie verborgen unter den Wellen. In der Zeit des {link:third-war}Dritten Krieges{/link} erhoben sie sich wieder, und eine Zeit lang dienten sie {link:illidan-stormrage}Illidan Stormrage{/link}.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Die Naga sind stolz, verbittert und ehrgeizig. Ihre Sirenen sind mächtige Zauberinnen, die über die Gewässer und die Stürme gebieten. Ihre Myrmidonen sind furchterregende Krieger. Es heißt, dass sie {link:azshara}Azshara{/link} in den Tiefen noch immer ehren.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Naga haben Küstenstriche in {link:azshara}Azshara{/link}, an der {link:darkshore}Dunkelküste{/link}, im {link:ashenvale}Eschental{/link} und in {link:desolace}Desolace{/link} in Besitz genommen. Sie suchen den überfluteten Tempel der {link:blackfathom-deeps}Blackfathom-Tiefe{/link} heim. Was sie an den Küsten Kalimdors suchen, wissen die {link:night-elves}Nachtelfen{/link} nicht.]=],
		},
	},
})

Translate("deDE", "satyrs", {
	title = "Satyrn",
	aliases = { "Satyr" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Satyrn sind Dämonen des Waldes, gehörnt und mit Bocksbeinen. Einst waren sie hochgeborene {link:night-elves}Nachtelfen{/link}, die sich an die {link:burning-legion}Brennende Legion{/link} verkauften. Nun suchen sie die verderbten Wälder des nördlichen {link:kalimdor}Kalimdor{/link} heim und verbreiten die Verseuchung der {link:fel-magic}Teufelsmagie{/link}, wohin sie auch gehen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Im {link:war-of-the-ancients}Krieg der Ahnen{/link} war Lord Xavius, der Berater von {link:queen-azshara}Königin Azshara{/link}, der erste der Hochgeborenen, der den Dämonen diente. Nach seiner Niederlage formte ihn der Herr der Legion zum ersten Satyr um. Xavius wiederum brachte viele der Hochgeborenen zum selben Schicksal. Die Satyrn kämpften den ganzen Krieg hindurch für die Legion, und viele überlebten die Teilung.]=],
		},
		{
			title = "Wesen und Bräuche",
			text = [=[Satyrn sind grausam, hinterlistig und machthungrig. Sie dienen den Dämonen, ob die Legion nah oder fern ist. Ihre Magie ist {link:fel-magic}Teufelsmagie{/link}, und sie verderben das Land, in dem sie hausen. Ihre Stämme leben in finsteren Hainen in den Wäldern, die sie verwüsten.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Satyrn haben sich seit dem Dritten Krieg in den Wäldern ausgebreitet. Sie befallen den {link:felwood}Teufelswald{/link} und das {link:ashenvale}Eschental{/link}, wo {link:satyrnaar}Satyrnaar{/link} ihre Hochburg ist, und sie lauern in den Ruinen von {link:azshara}Azshara{/link} und in den Tiefen von {red:dire-maul}Düsterbruch{/red}. Die {link:sentinels}Schildwachen{/link} jagen sie ohne Erbarmen.]=],
		},
	},
})
